const niches = {
'home-services':{name:'Home Services',buyers:'independent contractors, roofers, plumbers and HVAC companies',problem:'missed leads and slow estimate follow-up',offer:'AI-assisted enquiry intake and appointment follow-up',deliver:['Audit enquiries and appointment booking friction','Set up approved intake and follow-up workflows','Build a simple pipeline with human handoff','Report enquiry response time and qualified appointments']},
'restaurants':{name:'Hospitality',buyers:'independent restaurants and cafés',problem:'inconsistent repeat visits and missed guest enquiries',offer:'Opt-in guest retention and content operations',deliver:['Build a permission-based guest audience','Create a weekly promotions and content calendar','Improve incoming booking enquiry handling','Track repeat reservation enquiries']},
'real-estate':{name:'Real Estate',buyers:'independent agents and boutique property teams',problem:'unanswered buyer enquiries and repetitive listing content',offer:'Listing promotion and buyer enquiry workflows',deliver:['Prepare compliant listing content from approved facts','Map lead qualification and response flow','Create human-reviewed follow-up drafts','Track qualified buyer conversations']},
'ecommerce':{name:'Commerce',buyers:'small ecommerce brands',problem:'creative fatigue and inconsistent offer testing',offer:'Product creative and lifecycle campaign operations',deliver:['Develop three distinct product angles','Create testable short-form content briefs','Review consent-based lifecycle messaging','Track creative-to-cart signals']},
'wellness':{name:'Wellness',buyers:'independent studios and fitness businesses',problem:'empty class capacity and poor rebooking',offer:'Membership engagement and rebooking operations',deliver:['Map opt-in retention journeys','Plan helpful educational content','Test consent-based rebooking campaigns','Track rebookings and class interest']},
'professional':{name:'Professional Services',buyers:'consultants, accountants and service specialists',problem:'manual lead intake and inconsistent authority content',offer:'AI-assisted lead intake and educational content',deliver:['Define the right-fit client profile','Streamline discovery and intake forms','Create approved educational content variants','Track qualified consultations']},
'creators':{name:'Creator Economy',buyers:'independent experts, coaches and creators',problem:'content bottlenecks and unclear paid offers',offer:'Creator-to-client content and sales operations',deliver:['Clarify a focused paid service offer','Create a repeatable content theme engine','Build an inquiry capture journey','Track qualified discovery requests']}
};
const voices = {premium:'confident, polished and practical',direct:'clear, direct and value-focused',curious:'curiosity-driven and educational',bold:'challenging conventional assumptions without exaggerated claims'};
const goals={leads:'qualified enquiries',awareness:'attention and useful engagement',clients:'first real client conversations',retention:'repeat business'};
function buildKit(i) {
const n=niches[i.niche]||niches['home-services'], voice=voices[i.style]||voices.premium, g=goals[i.goal]||goals.leads, platform=(String(i.platform||'Instagram Reels')).slice(0,40);
const topic=n.problem, outcome=g;
const hooks=[
'Your next growth problem might not be leads. It might be '+topic+'.',
'If you serve '+n.buyers+', check this before buying another marketing tool.',
'Three things I would change about the way a '+n.name.toLowerCase()+' business follows up with buyers.',
'What an AI workflow can do—and what a human should still approve.',
'Here is the process behind '+outcome+': one problem, one offer, one test.',
'I mapped a simple system for '+n.buyers+'. Here is what I would measure first.',
'The biggest mistake in marketing automation? Automating a broken process.',
'You do not need 12 tools. You need one measurable workflow for '+n.name.toLowerCase()+'.',
'From missed enquiry to human response: a practical AI process in 30 seconds.',
'Before and after: how to map a process without pretending it guarantees results.'
];
const ads=[
'Are your '+n.name.toLowerCase()+' enquiries slipping through the cracks? Find the handoff that slows things down. See a practical workflow map for '+n.buyers+'. CTA: Get a free assessment.',
'What if every interested buyer reached a clear next step? We help '+n.buyers+' examine '+topic+' using responsible automation. CTA: Explore a sample workflow.',
'Stop guessing which marketing task to automate. Start with the step you can measure. Built for '+n.buyers+'. CTA: See the launch checklist.'
];
return {title:n.name+' AI Agency Launch Kit',platform,intro:'Positioning, content and acquisition drafts for '+platform+' in a '+voice+' voice, focused on '+outcome+'.',headline:n.name+' Growth Workflow',positioning:'We help '+n.buyers+' address '+topic+' with '+n.offer.toLowerCase()+'. We start with a bounded pilot and measure the actual outcome.',offer:'Starter offer: A 14-day diagnostic and workflow pilot. Deliver one defined process, a training handoff and a before/after measurement plan. Scope and price based on real client complexity.',deliverables:n.deliver,
hooks,ads,script:'0–3 sec: '+hooks[0]+'\n3–10 sec: Show where the process fails: '+topic+'.\n10–23 sec: Explain a practical solution: '+n.offer+'.\n23–30 sec: Explain what is measured: response time, qualified enquiries and human review.\n30–35 sec: CTA: Get a free workflow map.\n\nVisual direction: clean close-ups, labelled workflow diagrams and actual process screenshots. Avoid fake earnings or fabricated testimonials.',
outreach:'SUBJECT: A workflow idea for '+n.name.toLowerCase()+' teams\n\nHi [first name],\n\nI have been looking at the way '+n.buyers+' manage '+topic+'. I work on '+n.offer.toLowerCase()+' and can share a short sample workflow covering the steps to test, the human review points and how to measure an outcome.\n\nWould a quick overview be useful?\n\n[Your name + business identity]\n\nOnly send where permitted by relevant anti-spam laws; include identification and unsubscribe details where required.',
plan:['Interview five buyers to validate whether '+topic+' is an urgent paid problem.','Define a clear starter deliverable and a simple pilot price based on the effort.','Publish two useful '+platform+' posts without financial or performance guarantees.','Create a landing page and an opt-in enquiry form.','Send compliant, individually relevant outreach to appropriately permitted recipients.','Book discovery conversations and identify what each buyer actually needs.','Review engagement and real conversations, revise offer and select the next experiment.']};}

